class _Dropout30C(nn.Module):
    def __init__(self, rate):
        super().__init__()
        self.dropout = nn.Dropout(rate)
        self.rate = rate
    def forward(self, x, lp):
        b = x.shape[0]
        t = x.shape[1]
        ne = x.shape[-1]
        k = int(ne*self.rate)
        if self.training:
            xperm = torch.randperm(b*t*ne,device=x.device)
            xperm = xperm.reshape((b,t,ne))
            ### randomly select k
            v,idx = xperm.topk(k,dim=-1)
            keep = xperm<v.min(-1)[0].unsqueeze(-1)

            # keep = torch.rand(x.shape,device=x.device) < (1-self.rate)
            lpp = ((math.log(1-self.rate))*keep + (1-keep)*math.log(self.rate)).reshape((x.shape[0],-1)).sum(-1)
            lp  = lp+lpp
            x = x*keep
            # x = self.dropout(x)
        else:
            x = x

        return x,lp


class Block30C(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention30C(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLP30C(config)

    def forward(self, x, x0, lp):
        dx,lp = self.attn(self.ln_1(x),self.ln_1(x0), lp)
        x = x + dx
        dx,lp = self.mlp(self.ln_2(x), lp)
        x = x + dx
        return (x,lp)


class MLP30C(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.gelu    = nn.GELU()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        # self.dropout = nn.Dropout(config.dropout)
        self.dropout = _Dropout30C(config.dropout)

    def forward(self, x, lp):
        x = self.c_fc(x)
        x = self.gelu(x)
        x = self.c_proj(x)
        x,lp = self.dropout(x,lp)
        return x,lp


