class Block20F(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        # self.attn = CausalSelfAttention(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        # self.mlp = MLP11(config)
        # self.mlp = MLP(config)
        ne = config.n_embd
        ng = config.n_head
        nk = ne
        self.nk = nk

        self.k_attn_1a = nn.Linear(ne, ne,bias=config.bias)
        self.k_attn_1c = nn.Linear(ne, ng*ne,bias=config.bias)
        self.k_attn_1d = nn.Linear(ne, ng*ne,bias=config.bias)
        self.kvec      = nn.Linear(ne, nk,bias=config.bias)
        self.k_proj      = nn.Linear(nk, ne,bias=config.bias)
        self.c_proj    = nn.Linear(ne, ne,bias=config.bias)


    def forward(self, x0, x):
        ne = x0.shape[-1]
        b,t = x0.shape[:2]
        device= x0.device
        nk = self.nk
        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
        att_mask      = torch.tril(att_mask, diagonal=-1)
        att_mask[0,0] =True
        x0 = _lnorm(x0)

        xq1 = self.k_attn_1c(x0).reshape((b,t,-1,ne))
        xq = (self.k_attn_1a(_lnorm(x)))
        engp = torch.einsum('bpke,bte->btpk', xq1, xq) / ne**0.5
        engp = engp.masked_fill(att_mask[None,:t,:t,None] == 0, float('-inf'))


        # kvec = _lnorm(self.kvec.weight.T)
        # kq   = self.k_attn_1c(kvec).reshape((nk,-1,ne))
        # engk = torch.einsum('vke,bte->btvk', kq, xq) / ne**0.5
        # enga = torch.cat([engp,engk],dim=2)
        enga = engp
        att  = enga.reshape((b,t,-1)).softmax(-1).reshape(enga.shape)

        ### use v vector in ca

        yinput = torch.einsum('btpk,bpke->bte',att[:,:,0:t],xq1) 
        x = (x + self.c_proj(yinput) + self.k_proj(self.kvec(x).relu()))

        return x


