                ### getting the output position
                wk     = block0.k_attn_2.weight.T
                xq     = dx1.matmul(wk)
                xq    = lnorm(xq)
                engk   = torch.einsum('bte,btke->btk',xq , int_state)  / (ne ** 0.5)
                att    = engk.softmax(-1)
                # yinput2= torch.einsum('btk,btke->bte', att[:,:,:ng], int_state) 
                atto   = att
                # atto3  = att

                ### getting the other effect
