                xq     = dx1.matmul(wk)
                xq    = lnorm(xq)
                engk   = torch.einsum('bte,btke->btk',xq , int_state)  / (ne ** 0.5)
                att    = engk.softmax(-1)
                atto2  = att

                ### getting the applied matrix without change in pointer
                wk     = block0.k_attn_4.weight.T
                xq     = dx1.matmul(wk)
                xq    = lnorm(xq)
                engk   = torch.einsum('bte,ke->btk',xq , knorm)  / (ne ** 0.5)
