                if layer_i == (nl // 2)*0:           
                    int_state[:,:,-4] += xn[:,::2]        
                    int_state = _lnorm(int_state)
                elif layer_i == (nl // 2)*1:     
                    int_state[:,:,-3] += xn[:,1::2]        
                    int_state = _lnorm(int_state)
                    output[:,:,0] = int_state[:,:,-2]
