                att    = engk.softmax(-1)
                # att    = muatt(att)
                yinput7= torch.einsum('btk,btke->bte', att, int_state)
                atto7   = att

                ### getting the applied matrix without change in pointer
                wk     = block0.k_attn_8.weight.T
                xq     = dx1.matmul(wk)
