                    # flayer2 = nn.Linear(ne*(3+1),    ne,bias=False),
                    flayer2 = nn.Linear(ne*(3)*ng,    ne,bias=False),
                    flayer3 = nn.Linear(ne*(3)*ng,    ne,bias=False),
