                int_state += (atto3+ atto4 +  atto5 +  atto7).unsqueeze(-1) * kenc(ctx, block0.flayer4.weight)
                # int_state += atto4.unsqueeze(-1) * kenc(ctx, block0.flayer4.weight)
                # int_state += atto7.unsqueeze(-1) * kenc(ctx, block0.flayer4.weight)
