            x2  = nn.Linear(ne,ne,bias=False),
            drop = nn.Dropout(config.dropout),
            
            # gate_attn = nn.Linear(ne, ne*(nh+1),bias=False),
            final_output = nn.Linear(ne*(nl), ne,bias=False),
            gate_attn = nn.Linear(ne*(ng+1), ng,bias=True),
