        int_state = int_emb + pos_emb[None,:,None]
        int_state[:,:,0] += xn        

        int_state = _lnorm(int_state)        

        def lnorm(x):
            x = x/(0.001+x.std(-1,keepdim=True))
            return x

        for ii in range(1):

            for layer_i in range(nl):                
                '''
                step 1250: train loss 3.8440, val loss 4.7829
                '''
