                    # # flayer2 = nn.Linear(ne*(nc)*ng,    ne,bias=False),
                    # flayer3 = nn.Linear(ne*(nc)*ng,    ne,bias=False),
                    # # flayer2b = nn.Linear(ne*(2),    ne,bias=False),
                    # flayer4 = nn.Linear(ne*(nc)*ng,    ne,bias=False),
                    # flayer7 = nn.Linear(ne*(nc)*ng,    ne,bias=False),
