            fig, axs = plt.subplots(1,1,figsize=[8,8])
            ax = axs
            out = np.zeros((nl,ng))
            for li, block0 in enumerate(self.transformer.h):
                out[li] = block0.flayer3.weight.reshape((ng,-1,e)).square().mean((1,2)).cpu().detach().numpy()


            
