                    k_attn_2 = nn.Linear(ne, ne,bias=False),
                    k_attn_3 = nn.Linear(ne, ne,bias=False),
                    k_attn_6 = nn.Linear(ne, ne,bias=False),
                    kvec = nn.Linear(ng, ne,bias=False),
