            dx1    = int_state[:,:,1]

            wk     = block0.k_attn_2.weight.T
            xq     = dx1.matmul(wk)
            xq     = lnorm(xq)
            engp   = torch.einsum('bte,bpe->btp',xq , int_state[:,:,-3])  / (ne ** 0.5)
            engp   = engp.masked_fill(att_mask[None,:t,:t] == 0, float('-inf'))
            att    = engp.softmax(-1)
            yinput2= torch.einsum('btp,bpe->bte', att, int_state[:,:,-3])
