        int_emb_3   = self.transformer.wpe3(torch.zeros((b,t,ng),device=device).long() 
            + torch.arange(ng,device=device)[None,None,])

        t = t + pad
        x = self.transformer.drop(tok_emb + pos_emb)
        # x = (tok_emb + pos_emb)
        
        
        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
