                att    = engp.reshape((b,t,-1)).softmax(-1).reshape((engp.shape))
                yinput = torch.einsum('btpk,bpke->bte', att, md.input_tok(dx2).reshape((b,t,-1,ne)))
                # tok_eff = torch.einsum('btk,btke->bte',att.sum(2), md.input_tok(xtok0).reshape((b,t,-1,ne)))
