class CCM305F12(GPT):
    '''
    similar to 305F5
    selecting token and construct a series
    selecting token instead of context
    '''

    def __init__(self, config):
        super(GPT,self).__init__()
        assert config.vocab_size is not None
        assert config.block_size is not None
        config.optimizer ='rmsprop'
        config.optimizer ='adamw'
        # config.optimizer ='adam'
        self.config = config
        pad = 20
        # config.block_size = config.block_size + pad
        config.g = 100
        nl = config.n_layer
        ne = config.n_embd
        config.ng = config.n_head
        # config.share_layer = False
        ng = config.ng
        nh = config.n_head
        nc = 1


        
        self.transformer = nn.ModuleDict(dict(
            wte  = nn.Embedding(config.vocab_size, config.n_embd),
            wpe  = nn.Embedding(config.block_size + pad, config.n_embd),
            wpe2 = nn.Embedding(config.block_size + pad, config.n_embd),
            drop = nn.Dropout(config.dropout),
            output = nn.Linear(ne*(nl+1), ng*ne,bias=False),
            gates = nn.Linear(ne*(nl+1), 1, bias=True),
            
            input = nn.Linear(ne, (1+1)*ne,bias=False),
            input_tok = nn.Linear(ne, (ng)*ne,bias=False),
            # input2 = nn.Linear(ne, (ng)*ne,bias=False),


            h = nn.ModuleList([ nn.ModuleDict(
                dict(
                    k_attn_1 = nn.Linear(ne, ne,bias=False),
                    k_attn_1c = nn.Linear(ne*(1+nll), ng*ne,bias=False),
                    k_attn_1b = nn.Linear(ne, ne,bias=False),
                )
                ) for nll in range(config.n_layer if not config.share_layer else 1) 
                ]),
            # fout = nn.Linear(ne*(nc)*20,    ne,bias=False),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))

        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))
                # torch.nn.init.normal_(p, mean=0.0, std=1)
                # //math.sqrt(2 * config.n_layer))



    def forward(self, idx, targets=None, is_stats=False):



        g  = self.config.g
        ng = self.config.ng
        e  = self.config.n_embd
        ne = self.config.n_embd

        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)


        def kenc(ctx, weight):
            yout = torch.einsum('btf,kfe->btke', ctx,weight.reshape((ng,-1,e)))
            return yout

        pad = 0

        lreg = 0.
        lreg_factor = 0.0


        tok_emb   = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb   = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        # pos_emb[:pad]= pos_emb_2[:pad]
        xtok0 = tok_emb #+ pos_emb[None,:,None]
        xtok0 = _lnorm(xtok0)

        ### init internal embedding
        ### ng is the number of internal vectors
        int_emb     = self.transformer.wpe2(torch.zeros((b,t,ng),device=device).long() 
            + torch.arange(ng,device=device)[None,None,])

        t = t + pad
        x = _lnorm(tok_emb + pos_emb)
        
        
        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
        att_mask      = torch.tril(att_mask, diagonal=0)
        att_mask[0,0] =True


        md = self.transformer
        dx    = 0.
        nstep = 1

        nl = self.config.n_layer
        nh = self.config.n_head

        dx = 0.
        block0 = self.transformer.h[0]

        # int_state = self.transformer.drop(md.input(tok_emb).reshape((b,t,-1,ne)) + pos_emb[None,:,None])
        kemb = md.input_tok(tok_emb).reshape((b,t,-1,ne))
        # int_state = md.drop(kemb + pos_emb[None,:,None])
        int_state = (kemb + pos_emb[None,:,None])
        int_state = _lnorm(int_state)      
        xtok = int_state[:,:,0]
        int_state = int_state[:,:,1:]


  
        def lnorm(x):
            x = x/(0.001+x.std(-1,keepdim=True))
            return x

        int_states = torch.zeros((b,t,nl+1,e),device=device)
        int_states[:,:,0] = int_state[:,:,0]

        for ii in range(1):

            for layer_i in range(nl):                
                if not self.config.share_layer:
                    ### variable layer
                    block0 = self.transformer.h[layer_i]
                else:
                    ### constant layer
                    block0 = self.transformer.h[0]

                dx1    = int_state[:,:,0]
                dx2    = int_states[:,:,:layer_i+1].reshape((b,t,-1))
                xq2    = _lnorm(block0.k_attn_1c(dx2).reshape((b,t,-1,ne)))
                xq     = lnorm(dx1)

                engp   = torch.einsum('btke,bpe->btpk', xq2, xq)  / (ne ** 0.5)
                engp   = engp.masked_fill(att_mask[None,:t,:t,None] == 0, float('-inf'))
                att    = engp.reshape((b,t,-1)).softmax(-1).reshape((engp.shape))
                yinput = torch.einsum('btpk,bpke->bte', att, _lnorm(md.input_tok(tok_emb).reshape((b,t,-1,ne))))
                yo1 = yinput


                # yo1 = (yo1)
                int_states[:,:,layer_i+1] = int_states[:,:,layer_i+1] + yo1
                # int_state[:,:,0] 
                
                if not self.training and not self.config.compile:
                    if layer_i ==0:
                        print()


        x = int_states[:,:,:]



        ### btk
        x     = x.reshape((b,t,-1))
        att   = md.gates(x).softmax(-1)
        outs = md.output(x)
        x = outs.reshape((b,t,-1,ne))
        # x     = torch.einsum('btk,btke->bte',att, outs)
        x = _lnorm(x)
        x0 = x

        if self.training and targets is not None:

            # sig = 0.01
            # sig = 0.1
            sig = 1.
            isqsig = 1./sig**2
            # logq = -0.5* isqsig*(x - x2).square().sum(-1).sum(-1)
            ### get posterior
            x2 = x + md.wte(targets).unsqueeze(-2)
            x2 = _lnorm(x2)
            ### xsample
            # x = x2 + torch.normal(0., sig, x2.shape,device=device)
            x = x2

            ### dist to post
            ### this entropy is fixed, and thus not included
            logq = -0.5* isqsig*(x - x2).square().sum(-1).sum(-1)

            ### dist to prior
            logw = -0.5 * isqsig*(x-x0).square().sum(-1).sum(-1)

            vloss = (- logw).reshape(-1)
        else:
            vloss = 0.


        # x = self.transformer.ln_f(x)                
        x = x[:,pad:]

        atts = int_states
        self.add_stats("atts", atts, is_stats)
        self.add_stats("int_states", int_states, is_stats)
        # self.add_stats("int_states_norm", int_states.square().mean(-1), is_stats)
        self.add_stats("final_gates",  att, is_stats)

        if is_stats:
            gate_out_v, gate_out_k = self.lm_head(outs).topk(dim=-1,k=10)
            self.add_stats("gate_out_k", gate_out_k, is_stats)
            self.add_stats("gate_out_v", gate_out_v, is_stats)

            wemb =  md.input_tok(((self.lm_head.weight))).reshape((-1,ng,ne))
            logits = torch.einsum( 'btle,nke->btlnk', int_states, wemb ).reshape((b,t,nl+1,-1))
            v, k = logits.topk(dim=-1,k=10)
            self.add_stats("int_states_k", k//ng, is_stats)
            self.add_stats("int_states_k_n", k%ng, is_stats)
            self.add_stats("int_states_v", v, is_stats)


        if targets is not None:
            # if we are given some desired targets also calculate the loss




            if self.training:
                ### select the x most similar to output token
                engp = torch.einsum('btke,bte->btk', x, md.wte(targets))
                # .unsqueeze(-2))
                v , idx = engp.max(dim=-1)
                engp   = engp.masked_fill(engp!=v.unsqueeze(-1), 0.0)
                engp   = engp.masked_fill(engp==v.unsqueeze(-1), 1.0)
                att = engp
                x = torch.einsum('btke,btk->bte',x,att)

                # x = torch.gather(x,dim=2,index=idx.unsqueeze(-1).unsqueeze(-1).expand((b,t,1,ne)))[:,:,0]

                logits = self.lm_head(x)

                final_out_v, final_out_k = logits.topk(dim=-1,k=10)
                self.add_stats("final_out_k", final_out_k, is_stats)
                self.add_stats("final_out_v", final_out_v, is_stats)

                # loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1)

                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1,reduction='none')
                loss = loss + vloss
                loss = loss  - math.log(1./ng)
            else:
                logits = self.lm_head(x)
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.unsqueeze(-1).expand((b,t,ng)).reshape(-1), ignore_index=-1,reduction='none')
                loss = (loss - math.log(1./ng)).reshape((b,t,ng))
                loss = -(-loss).logsumexp(-1).reshape(-1)
                loss = loss + vloss



            self.add_stats("logp", -loss.reshape((b,t)), is_stats)
            loss = loss.mean()

        else:
            # inference-time mini-optimization: only forward the lm_head on the very last position
            logits = self.lm_head(x[:, [-1], :]) # note: using list [-1] to preserve the time dim
            loss = None


        return logits, loss  

        return logits, loss  


    def plot(self,fn):

        md = self.transformer

        g  = self.config.g
        ng = self.config.ng
        e  = self.config.n_embd
        ne = self.config.n_embd
        device = self.lm_head.weight.device
        nl = self.config.n_layer




        import matplotlib; matplotlib.use('agg')
        import matplotlib.pyplot as plt
        # import 
        with open(fn,'w') as f:
            
            fig, axs = plt.subplots(1,2,figsize=[8,8])
            axi = -1
            axs=axs.ravel()
            axi+=1;ax = axs[axi]
            # out = np.zeros((nl,ng))
            x = md.output.weight.T.reshape(((1+nl),ne,-1,ne))
            x = x.square().mean((1,3))
            x = x.cpu().detach().numpy()
            out = x
            
            # im = ax.pcolormesh(out,vmin=out.min(),vmax=None)
            # im = ax.pcolormesh(out,vmin=0,vmax=None)
            im = ax.pcolormesh(out)
            plt.colorbar(im)

            axi+=1;ax = axs[axi]
            x = md.gates.weight.T.reshape(((1+nl),ne,-1,))
            x = x.square().mean((1,))
            x = x.cpu().detach().numpy()
            im = ax.pcolormesh(x)
            plt.sca(ax)
            plt.title('gates')
            # im = ax.pcolormesh(out,vmin=0,vmax=None)
            plt.colorbar(im)
            plt.savefig(fn+'.png')
            plt.close()
            # ax.heatma

        pass



