        t = t + pad
        x = (tok_emb + pos_emb)        
        
        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
        att_mask      = torch.tril(att_mask, diagonal=0)
        att_mask[0,0] =True


        md = self.transformer

        nl = self.config.n_layer
        nh = self.config.n_head

        dx = 0.
        block0    = self.transformer.h[0]
        kemb      = md.input(tok_emb).reshape((b,t,-1,ne))
