                dx1    = int_state[:,:,0]
                dx2    = int_states[:,:,:layer_i+1].reshape((b,t,-1))
                dx2    = block0.k_attn_1c(dx2).reshape((b,t,-1,ne))
                kvec = block0.kvec.weight.T

                xq2    = _lnorm(dx2)
                xq     = lnorm(dx1)

                engp   = torch.einsum('bte,bpke->btpk', xq, xq2)  / (ne ** 0.5)
