    def forward(self, idx, targets=None):
        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)

        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        # ns = 10
        ns = 3
        # if self.training:
        #     # ns = 3
        #     ns = 10
        # else:
        #     ns = 1
        ne = self.config.n_embd
        x = self.transformer.ln_f(x)
        x = x[None].repeat((ns,1,1,1)).reshape((-1,x.shape[1],x.shape[2]))
        lp = torch.zeros((x.shape[0],x.shape[1]),device=device)
        nl = self.config.n_layer
        xf = torch.zeros((b*ns,t-1,nl+1,ne),device= device)
        xb = torch.zeros((b*ns,t,nl+1,ne),device= device)
        ### forward
        x0 = x

        ### backward
        x = x0
        i=0
        xb[:,:,nl-i] = x
        for block in self.transformer.hpost:
            i+=1
            x,_ = block(x, x0[:,:],lp)
            # x = x+torch.sam
            if i+1==nl:
                x = self.transformer.ln_f(x)
            xb[:,:,nl-i] = x

        ### discard the first
        xb = xb[:,1:]

        i=0
        x = x0[:,:-1]
        xf[:,:,i] = x
        for _,block in enumerate(self.transformer.h):
            i+=1
            xnext, _ = block(x,x0[:,:-1], lp[:,:-1])
            if i+1==nl:
                xnext = self.transformer.ln_f(xnext)
            xf[:,:,i] = xnext
            x = xb[:,:,i]
        # x = self.transformer.ln_f(x)
        sigma = 0.05
        sigma = 1.
        invsqsigma = 1./sigma**2

        if targets is not None:
            # if we are given some desired targets also calculate the loss
            
            if not self.training:
                x = x0
                for _,block in enumerate(self.transformer.h):
                    x, _ = block(x,x0, lp)
                x = self.transformer.ln_f(x)
                logits = self.lm_head(x) #
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None,].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                loss = loss.mean()               
            else:
                ### use the last but one variable
                # logits = self.lm_head(xb[:,:,-2]) 
                logits = self.lm_head(xf[:,:,-1]) 
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None,:,:-1].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                lpy  = -loss
                
                ### weight by likelihood                
                lpz  = -invsqsigma * ((xf - xb)[:,:,:-1,:]).square().sum(-1).mean(-1)
                elbo = (lpy + lpz.reshape(-1))
                loss = -(elbo).mean() 
        else:
            # inference-time mini-optimization: only forward the lm_head on the very last position
            logits = self.lm_head(x[:, [-1], :]) # note: using list [-1] to preserve the time dim
            loss = None

        return logits, loss



