class MLPsoftplus(nn.Module):
    # act = nn.Softplus()
    

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.gelu    = nn.GELU()
        self.act     = nn.Softplus()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x = self.c_fc(x)
        # x = self.gelu(x)
        # dy = 0.5
        # dy = 1.5
        # dy = 2.5
        # dy = 4.5
        dy = 6.5
        # dy = -2.5
        x = self.act(x+dy) - dy
        x = self.c_proj(x)
        x = self.dropout(x)
        return x





class MLPswish(nn.Module):
    # act = nn.Softplus()
    

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.gelu    = nn.GELU()
        self.act     = nn.Sigmoid()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x = self.c_fc(x)
        x = x * self.act(x)
        x = self.c_proj(x)
        x = self.dropout(x)
        return x




class MLPmix(nn.Module):
    # act = nn.Softplus()
    

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.gelu    = nn.GELU()
        # self.act     = nn.Sigmoid()
        self.mixer  = nn.Linear(4 * config.n_embd, 2, bias=config.bias)
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x = self.c_fc(x)
        # xm = ((x.unsqueeze(-1) - self.mixer.weight.T[None,None]).abs()-0.5)
        xm = ((x.unsqueeze(-1) - self.mixer.weight.T[None,None]).abs()- 0.5)

        x = torch.cat([x.unsqueeze(-1).relu(), (-xm).relu()-0.25],dim=-1).logsumexp(-1)
        # x = x * self.act(x)
        x = self.c_proj(x)
        x = self.dropout(x)
        return x



class MLPsoftplus2(nn.Module):
    

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.gelu    = nn.GELU()
        self.act     = nn.Softplus()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x = self.c_fc(x)
        # x = self.gelu(x)
        # dy = 4.5
        # dy = 6.5
        # dy = -2.5
        # x = self.act(x+dy) - dy

        dy = 1.5
        x = self.act(x-dy)
        x = self.c_proj(x)
        x = self.dropout(x)
        return x


class Block102D(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention101B(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLPsoftplus2(config)

        # self.mlp  = MLPmix(config)
        # self.mlp  = MLPswish(config)
        # self.mlp  = MLPsoftplus2(config)

    def forward(self, x, x0,):
        dx = self.attn(self.ln_1(x),self.ln_1(x0),)
        x = x + dx
        dx = self.mlp(self.ln_2(x))
        x = x + dx
        return x


