class MLP102F(nn.Module):
    

    def __init__(self, config):
        super().__init__()
        self.c_fc    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=False)
        self.gelu    = nn.GELU()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.c_proj2  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x0 = x
        x1  = self.c_fc(x0)
        x2  = self.c_fc2(x0)
        # x = self.gelu(x)
        x = 0
        x += self.c_proj(x1.sigmoid() * x1)
        x += self.c_proj2(x1.sigmoid() * x2)
        # x = self.act(x+dy) - dy
        # x = self.c_proj(x)
        x = self.dropout(x)
        return x

