class MLP102H(nn.Module):
    

    def __init__(self, config):
        super().__init__()
        self.c_fc1    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc3    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc4    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=False)
        self.gelu    = nn.GELU()
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.c_proj2  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.c_proj3  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x0 = x
        x1  = self.c_fc1(x0)
        x2  = self.c_fc2(x0)
        x3  = self.c_fc3(x0)
        x4  = self.c_fc4(x0)
        # x = self.gelu(x)
        # xx = x3.softmax(-1)
        # xx = (x1/x.shape[-1]**0.5).softmax(-1)
        # xx = (x3/x.shape[-1]**0.5).sigmoid()
        xx = (x1).sigmoid()
        # softmax(-1)
        x = 0
        x += self.c_proj (xx * x4)
        x += self.c_proj2(xx * x2)
        x += self.c_proj3(xx * x3)
        # x = self.act(x+dy) - dy
        # x = self.c_proj(x)
        x = self.dropout(x)
        return x


