class MLP111(nn.Module):
    

    def __init__(self, config, d_mlp=None):
        super().__init__()
        if d_mlp is None:
            d_mlp = 4 * config.n_embd

        self.c_fc_pre    = nn.Linear(config.n_embd, d_mlp, bias=config.bias)
        self.c_fc    = nn.Linear(config.n_embd, d_mlp, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, d_mlp, bias=config.bias)
        self.c_fc3    = nn.Linear(config.n_embd, d_mlp, bias=config.bias)
        # self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=False)
        self.gelu    = nn.GELU()
        self.c_proj  = nn.Linear(d_mlp, config.n_embd, bias=config.bias)
        self.c_proj2  = nn.Linear(d_mlp, config.n_embd, bias=config.bias)
        self.c_proj_dm  = nn.Linear(d_mlp, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x, dm):
        x0 = x
        x1  = self.c_fc(x0)
        x2  = self.c_fc2(x0)
        x3  = self.c_fc3(x0) + self.c_fc_pre(dm)
        # xx = (x1/x.shape[-1]**0.5).softmax(-1)
        # xx = (x3/x.shape[-1]**0.5).sigmoid()
        xx = (x3).sigmoid()
        # print(xx.sum(-1).mean().item())
        # softmax(-1)
        x = 0
        x += self.c_proj (xx * x1)
        x += self.c_proj2(xx * x2)
        # x = self.act(x+dy) - dy
        # x = self.c_proj(x)
        dm = self.c_proj_dm(xx)
        dm = self.dropout(dm)
        x = self.dropout(x)
        return x,dm

class Block111(nn.Module):

    def __init__(self, config, d_mlp=None):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention101B(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.ln_3 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLP111(config, d_mlp)

    def forward(self, x, x0, dm):
        dx = self.attn(self.ln_1(x),self.ln_1(x0),)
        x = x + dx
        dx, dm = self.mlp(self.ln_2(x), self.ln_3(dm))
        x = x + dx
        return x,dm



