        x1  = self.c_fc(x0)
        x2  = self.c_fc2(x0)
        xx = (x1).sigmoid()

        # print(xx.sum(-1).mean().item())
        # softmax(-1)
        x = 0
        # x += self.c_proj (xx * x2)
        x += torch.einsum('btf,fe->bte', (xx * x2),self.c_proj.weight.T.softmax(-1))
        x = self.dropout(x)
        return x



