class MLP132(nn.Module):
    '''
    trying to write down an MLP with sparse intermediate representation
    '''
    

    def __init__(self, config):
        super().__init__()
        self.c_fc     = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc3    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc4    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)

        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.c_proj2  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        # self.c_proj2  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x):
        x0  = x
        x1  = self.c_fc(x0) * self.c_fc2(x0)
        x3  = self.c_fc3(x0)
        x4  = self.c_fc4(x0)

        xx = (x1).softmax(-1)

        # jac = torch.einsum('btk,ek,kf->btef',xx,self.c_fc3.weight.T, self.c_proj.weight.T)
        # jac = jac + torch.eye(x.shape[-1],device = x.device)[None,None]
        # print(jac.shape)
        # print(torch.det(jac).mean((0,1)).item())


        # print(xx.sum(-1).mean().item())
        x = 0
        x += self.c_proj (xx * x3)
        x += self.c_proj2 (xx * x4)
        # x += self.c_proj2(xx * x2)
        x = self.dropout(x)
        return x

class Block132(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention101B(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLP132(config)

    def forward(self, x, x0,):
        dx = self.attn(self.ln_1(x),self.ln_1(x0),)
        x = x + dx
        dx = self.mlp(self.ln_2(x))
        # f = lambda x:self.mlp(self.ln_2(x))
        # jac = torch.autograd.functional.jacobian(f,x)
        # print(torch.det(jac).mean((0,1)).item())
        x = x + dx
        return x


