            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            h0 = nn.ModuleList([Block117(config) for _ in range(1)]),
            h1 = nn.ModuleList( [Block117(config) for _ in range(1)] + [Block133(config) for _ in range(config.n_layer-1)] + []),
            # h1 = nn.ModuleList([Block130(config) for _ in range(config.n_layer-1)]),
            # +  [Block130(config) for _ in range(1)]),
