        for block in self.transformer.h1[:-1]:
            x = block(x,x1)

        block = self.transformer.h1[-1]

        # dist =  torch.distributions.normal.Normal(0.,1.)
        xdev = torch.normal(0.,1.,x.shape,device=x.device)
        # lpz = dist.log_prob(xdev).sum(-1)
        # x = x + xdev * self.logsigma.exp()
        if self.training:
            ### sampling from posterior
            x = (x) + xdev * self.logsigmapost.exp()
            ### lp is entropy, thus minimise neg entropy
            # loss_reg = -(self.logsigmapost)*x.shape[-1] 
            lpz = -0.5*(xdev/self.logsigmaprior.exp()).square() - self.logsigmaprior
            loss_reg = (-lpz - (self.logsigmapost)).sum(-1).view(-1)
            # loss_factor = 1./self.logsigmapost.exp()
            # loss_factor = (-self.logsigmapost*x.shape[-1] ).exp()
            loss_factor = 1.

        else:
            x = (x) + xdev * self.logsigmaprior.exp()
            loss_reg = 0.
            loss_factor = 1.

        x = block(x,x1)



        if targets is not None:
            # logits = (x*w)
            logits = self.lm_head(x*self.norm_w.exp())    
            # logits = logits  -(-self.lm_norm(xns.unsqueeze(-1))).square()
            ###(bte)
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
            loss = loss_factor*(loss+loss_reg)
            loss = loss.mean()

        return logits, loss       




