class Block177(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention101B(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        # self.mlp  = MLP171(config)

        ng = config.n_embd//2  ## number of neuron  *4/8
        self.att     = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc1    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc3    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc4    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc5    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc6    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc7    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_fc8    = nn.Linear(config.n_embd, ng, bias=config.bias)
        # self.c_fc9    = nn.Linear(config.n_embd, ng, bias=config.bias)
        self.c_proj1  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj2  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj3  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj4  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj5  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj6  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj7  = nn.Linear(ng, config.n_embd, bias=False)
        self.c_proj8  = nn.Linear(ng, config.n_embd, bias=False)
        self.dropout = nn.Dropout(config.dropout)


    def forward(self, x, x0,):
        ctx = self.attn(self.ln_1(x),self.ln_1(x0),)
        
        # x = dx
        x2=  self.ln_2(x)
        # att = (self.att(x2)/x.shape[-1]**0.5).softmax(-1)

        att = self.att(x2)
        ### zero out everything beside top2
        att = att.masked_fill(att<att.topk(2,dim=-1)[0].min(-1,keepdims=True)[0],float('-inf'))
        att = att.softmax(-1)


        # att = (self.att(x2)).softmax(-1)
        # att = (self.att(x2)*4).softmax(-1)
        xo = 0.
        xo = xo + self.c_proj1(self.c_fc1(ctx)*att) 
        xo = xo + self.c_proj2(self.c_fc2(ctx)*att) 
        xo = xo + self.c_proj3(self.c_fc3(ctx)*att) 
        xo = xo + self.c_proj4(self.c_fc4(ctx)*att) 
        xo = xo + self.c_proj5(self.c_fc5(ctx)*att) 
        xo = xo + self.c_proj6(self.c_fc6(ctx)*att) 
        xo = xo + self.c_proj7(self.c_fc7(ctx)*att) 
        xo = xo + self.c_proj8(self.c_fc8(ctx)*att) 
        # xo = xo + self.c_proj3(self.c_fc3(ctx)*att) 
        # xo = xo + self.c_proj4(self.c_fc4(ctx)*att) 
        return xo



