class Block191(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention101B(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        # self.mlp  = MLP171(config)
        self.nk = nk = config.n_embd 

        ## rank 5 internal
        self.ng = ng = config.n_rank
        self.ne = config.n_embd
        self.c_fc     = nn.Linear(config.n_embd, nk, bias=True)
        self.c_fc2    = nn.Linear(config.n_embd, nk*ng, bias=config.bias)
        # self.c_fc3    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.c_fc4    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        # self.c_proj3  = nn.Linear(4 * config.n_embd, config.n_embd, bias=False)
        # self.c_proj4  = nn.Linear(4 * config.n_embd, config.n_embd, bias=False)
        self.c_proj2  = nn.Linear( nk*ng, config.n_embd, bias=False)
        self.norm_w = nn.Parameter(torch.tensor(0.0))
        self.norm_w2 = nn.Parameter(torch.tensor(0.0))
        self.dropout = nn.Dropout(config.dropout)


    def forward(self, x, x0,):
        ctx = self.attn(self.ln_1(x),self.ln_1(x0),)
        
        # x = dx
        x2=  self.ln_2(x)
        att = self.c_fc(x2)
        ### zero out everything beside top2
        # att = att.masked_fill(att<att.topk(2,dim=-1)[0].min(-1,keepdims=True)[0],float('-inf'))
        att = (att*self.norm_w.exp()).softmax(-1)
        dist = torch.distributions.categorical.Categorical(probs=att)

        ### btk
        idxk = dist.sample()
        lp = dist.log_prob(idxk)
        
        ### we can simply follow the selected path now!!
        ne = self.ne
        ng = self.ng
        nk = self.nk

        zk = torch.einsum('bte,btef->btf',ctx,self.c_fc2.weight.reshape(nk,ne,ng)[idxk,:,:])
        zk = torch.einsum('btf,btfe->bte',zk, self.c_proj2.weight.reshape((nk,ng,ne))[idxk,:,:])
        # zk = zk*self.c_proj2.weight.T[idxk,:]


        xo = 0.
        xo = xo + self.norm_w2.exp()*zk
        # xo = xo + self.c_proj3(self.c_fc3(ctx)*att) 
        return xo,lp


