        ### 
        ### btk
        att  = self.k_att(self.ln_2(x))
        # att  = (att*self.norm_w.exp()).softmax(-1)
        att  = (att*self.norm_w.exp()).softmax(-1)
        dist = torch.distributions.categorical.Categorical(probs=att)
        idxk = dist.sample()
        lp   = dist.log_prob(idxk)
        # print(self.norm_w.exp().item())
        # print(idxk[0,:10])
        # print(att[0,:3,:10])
        ## tensor([ 4,  2,  6, 28, 21, 12,  4, 16, 11, 17], device='cuda:0')

        # ctx  = self.attn(self.ln_1(x),self.ln_1(x0), idxk)
        # xo   = ctx
        xo   = self.klin(self.ln_1(x0), att)

        return xo,lp







